  'barbell row':{name:'Rowing à la barre',description:'Tirage horizontal à la barre sollicitant le dos, les trapèzes et les biceps.',instructions:['Place-toi buste penché avec le dos neutre et la barre dans les mains.','Gaine le tronc et laisse les bras s’étendre.','Tire la barre vers le bas du ventre en ramenant les coudes derrière toi.','Redescends la barre lentement.'],tips:['Ne transforme pas le mouvement en extension lombaire.','Garde la barre proche du corps.','Contrôle la descente.']},
  'dumbbell row':{name:'Rowing à un bras avec haltère',description:'Tirage unilatéral ciblant principalement le grand dorsal et le haut du dos.',instructions:['Prends appui sur un banc et garde le dos neutre.','Laisse le bras travailler s’étendre vers le sol.','Tire l’haltère vers la hanche en ramenant le coude derrière toi.','Redescends lentement.'],tips:['Évite de tourner le buste.','Pense à tirer avec le coude.','Garde l’épaule éloignée de l’oreille.']},
  'seated cable row':{name:'Rowing assis à la poulie',description:'Tirage horizontal assis ciblant le milieu du dos et les dorsaux.',instructions:['Assieds-toi face à la poulie et place les pieds sur les supports.','Garde le dos neutre et les épaules basses.','Tire la poignée vers le bas du ventre en rapprochant les omoplates.','Retourne lentement les bras vers l’avant.'],tips:['Ne donne pas d’élan avec le buste.','Garde les coudes proches du corps.','Contrôle l’étirement.']},
  'barbell romanian deadlift':{name:'Soulevé de terre roumain à la barre',description:'Mouvement de charnière de hanche ciblant fortement les ischio-jambiers et les fessiers.',instructions:['Tiens la barre devant les cuisses avec les pieds stables.','Recule les hanches en gardant le dos neutre et les jambes légèrement fléchies.','Descends la barre le long des jambes jusqu’à sentir un bon étirement des ischio-jambiers.','Pousse les hanches vers l’avant pour revenir debout.'],tips:['La barre reste proche des jambes.','Ne cherche pas à toucher le sol à tout prix.','Garde le dos neutre pendant toute la répétition.']},
  'dumbbell romanian deadlift':{name:'Soulevé de terre roumain avec haltères',description:'Charnière de hanche avec haltères ciblant les ischio-jambiers et les fessiers.',instructions:['Tiens les haltères devant les cuisses.','Recule les hanches en gardant les genoux légèrement fléchis.','Descends les haltères près des jambes jusqu’à un étirement contrôlé.','Ramène les hanches vers l’avant pour te redresser.'],tips:['Garde les haltères proches du corps.','Ne courbe pas le bas du dos.','Priorise la tension musculaire plutôt que la profondeur.']},
  'bulgarian split squat':{name:'Fente bulgare',description:'Exercice unilatéral ciblant principalement les quadriceps et les fessiers.',instructions:['Place le pied arrière sur un banc et avance suffisamment le pied avant.','Descends en fléchissant la jambe avant tout en gardant le bassin stable.','Pousse dans le pied avant pour remonter.','Effectue toutes les répétitions puis change de côté.'],tips:['Garde le genou dans l’axe du pied.','Évite de pousser excessivement avec la jambe arrière.','Commence sans charge si nécessaire.']},
  'walking lunges':{name:'Fentes marchées',description:'Enchaînement de fentes en déplacement sollicitant quadriceps, fessiers et ischio-jambiers.',instructions:['Tiens-toi debout avec le tronc gainé.','Fais un pas en avant puis descends le bassin vers le sol.','Pousse dans le pied avant pour avancer et ramener les jambes.','Alterne les côtés sur chaque pas.'],tips:['Garde le buste stable.','Évite que le genou avant rentre vers l’intérieur.','Contrôle chaque appui.']},
  'leg extension':{name:'Leg extension',description:'Exercice d’isolation ciblant principalement les quadriceps.',instructions:['Installe-toi sur la machine avec les genoux alignés avec l’axe de rotation.','Place les chevilles derrière le rouleau et stabilise le bassin.','Tends les genoux pour lever le rouleau.','Redescends lentement jusqu’à la position de départ.'],tips:['Ne donne pas d’à-coups.','Contrôle particulièrement la descente.','Ajuste la machine avant de charger.']},
